-- tests/test_builder_sql.lua
-- SQL generated by the chainable builder (where, joins, groups, cursors, shortcuts).
-- Run: docker run --rm -v "$(pwd)":/app -w /app nickblah/lua:5.4 lua tests/test_builder_sql.lua

package.path = "./?/init.lua;./?.lua;" .. package.path

local Mock = require("tests.support.fivem_mock")
local T = require("tests.support.harness")

local mockResults = Mock.results
local reset = Mock.reset

-- ─── Test: Chainable Query Builder ─────────────────────────────────

T.section("Chainable Query Builder")

local BuilderLib = require("core.builder")

local b = BuilderLib.new("users", nil, nil)
local sql, params = b
    :where({ job = "police" })
    :where("money", ">", 100)
    :orderBy("money", "DESC")
    :limit(10)
    :offset(5)
    :toSQL()

T.match(sql, "SELECT %* FROM `users`", "builder base SELECT")
T.match(sql, "WHERE `job` = %?", "builder WHERE equality")
T.match(sql, "AND `money` > %?", "builder WHERE operator")
T.match(sql, "ORDER BY `money` DESC", "builder ORDER BY")
T.match(sql, "LIMIT 10", "builder LIMIT")
T.match(sql, "OFFSET 5", "builder OFFSET")

b = BuilderLib.new("users", nil, nil)
sql = b:leftJoin("profiles", "profiles.user_id", "users.identifier"):where({ job = "police" }):toSQL()
T.match(sql, "LEFT JOIN `profiles`", "builder LEFT JOIN")

b = BuilderLib.new("users", nil, nil)
sql = b:innerJoin("departments", "departments.id", "users.dept_id"):toSQL()
T.match(sql, "INNER JOIN `departments`", "builder INNER JOIN")

b = BuilderLib.new("users", nil, nil)
sql = b:rightJoin("logs", "logs.user_id", "users.id"):toSQL()
T.match(sql, "RIGHT JOIN `logs`", "builder RIGHT JOIN")

b = BuilderLib.new("users", nil, nil)
sql = b:select("job, COUNT(*) as cnt"):groupBy("job"):toSQL()
T.match(sql, "GROUP BY `job`", "builder GROUP BY")

b = BuilderLib.new("users", nil, nil)
sql, params = b:select("job, COUNT(*) as cnt"):groupBy("job"):having("COUNT(*) > ?", 5):toSQL()
T.match(sql, "HAVING COUNT", "builder HAVING clause")
T.eq(params[1], 5, "builder HAVING param correct")

b = BuilderLib.new("users", nil, nil)
sql, params = b:where({ id = { "IN", { 1, 2, 3 } } }):toSQL()
T.match(sql, "`id` IN %(%?, %?, %?%)", "builder WHERE IN")

b = BuilderLib.new("users", nil, nil)
sql, params = b:where({ money = { "BETWEEN", { 100, 1000 } } }):toSQL()
T.match(sql, "`money` BETWEEN %? AND %?", "builder WHERE BETWEEN")

b = BuilderLib.new("users", nil, nil)
sql = b:where({ name = { "LIKE", "%john%" } }):toSQL()
T.match(sql, "`name` LIKE %?", "builder WHERE LIKE")

b = BuilderLib.new("users", nil, nil)
sql, params = b:where({ deleted_at = { "IS", "NULL" } }):toSQL()
T.match(sql, "`deleted_at` IS NULL", "builder WHERE IS NULL")
T.eq(#params, 0, "builder IS NULL has no params")

b = BuilderLib.new("users", nil, nil)
sql = b:where({ status = { "!=", "banned" } }):toSQL()
T.match(sql, "`status` != %?", "builder WHERE !=")

b = BuilderLib.new("users", nil, nil)
sql, params = b:where({ job = "police" }):orWhere({ job = "medic" }):toSQL()
T.match(sql, "OR `job` = %?", "builder OR WHERE")

-- ─── Test: Builder new features ───────────────────────────────────

T.section("Builder New Features")

-- DISTINCT
b = BuilderLib.new("users", nil, nil)
sql = b:distinct():where({ job = "police" }):toSQL()
T.match(sql, "SELECT DISTINCT %*", "builder: SELECT DISTINCT")

-- whereNull / whereNotNull
b = BuilderLib.new("users", nil, nil)
sql = b:whereNull("deleted_at"):toSQL()
T.match(sql, "`deleted_at` IS NULL", "builder: whereNull")

b = BuilderLib.new("users", nil, nil)
sql = b:whereNotNull("email"):toSQL()
T.match(sql, "`email` IS NOT NULL", "builder: whereNotNull")

-- whereInSub with subquery
b = BuilderLib.new("users", nil, nil)
sql, params = b:whereInSub("id", "SELECT user_id FROM active_users WHERE score > ?", { 100 }):toSQL()
T.match(sql, "`id` IN %(SELECT user_id FROM active_users", "builder: whereIn subquery")
T.eq(params[1], 100, "builder: whereIn subquery params")

-- whereNotInSub with subquery
b = BuilderLib.new("users", nil, nil)
sql = b:whereNotInSub("id", "SELECT user_id FROM banned"):toSQL()
T.match(sql, "`id` NOT IN %(SELECT user_id FROM banned%)", "builder: whereNotIn subquery")

-- NOT IN operator in where
b = BuilderLib.new("users", nil, nil)
sql, params = b:where({ id = { "NOT IN", { 1, 2, 3 } } }):toSQL()
T.match(sql, "`id` NOT IN %(", "builder: NOT IN operator")

-- Cursor pagination: after
b = BuilderLib.new("users", nil, nil)
sql, params = b:after("id", 50):limit(10):toSQL()
T.match(sql, "`id` > %?", "builder: after cursor")
T.match(sql, "ORDER BY `id` ASC", "builder: after sets ORDER BY")
T.eq(params[1], 50, "builder: after cursor value")

-- Cursor pagination: before
b = BuilderLib.new("users", nil, nil)
sql, params = b:before("id", 50):limit(10):toSQL()
T.match(sql, "`id` < %?", "builder: before cursor")

-- Cursor DESC
b = BuilderLib.new("users", nil, nil)
sql = b:after("id", 50, "DESC"):toSQL()
T.match(sql, "`id` < %?", "builder: after DESC uses <")
T.match(sql, "ORDER BY `id` DESC", "builder: after DESC order")

-- ─── Test: whereExists on Builder ────────────────────────────────

T.section("Builder whereExists")

reset()
local Adapter = require("database.adapter")
local MySQLDriver = require("database.mysql")
local testAdapter = Adapter.new(MySQLDriver.new())

mockResults[1] = { { id = 1, name = "test" } }
b = BuilderLib.new("users", testAdapter)
b:whereExists("SELECT 1 FROM vehicles WHERE vehicles.owner_id = users.id")
sql, params = b:toSQL()
T.match(sql, "EXISTS", "whereExists: SQL contains EXISTS")
T.match(sql, "SELECT 1 FROM vehicles", "whereExists: contains subquery")

-- ─── Test: where() 2-arg shortcut ────────────────────────────────

T.section("where() 2-arg shortcut")

b = BuilderLib.new("users", nil, nil)
sql, params = b:where("job", "police"):toSQL()
T.match(sql, "`job` = %?", "where 2-arg: implicit = operator")
T.eq(params[1], "police", "where 2-arg: correct param value")

b = BuilderLib.new("users", nil, nil)
sql, params = b:where("money", 1000):toSQL()
T.match(sql, "`money` = %?", "where 2-arg: works with numbers")
T.eq(params[1], 1000, "where 2-arg: number param correct")

-- orWhere 2-arg shortcut
b = BuilderLib.new("users", nil, nil)
sql, params = b:where("job", "police"):orWhere("job", "medic"):toSQL()
T.match(sql, "OR `job` = %?", "orWhere 2-arg: implicit = operator")
T.eq(params[2], "medic", "orWhere 2-arg: correct param")

-- ─── Test: Builder shortcuts ─────────────────────────────────────

T.section("Builder shortcuts")

-- whereIn with array
b = BuilderLib.new("users", nil, nil)
sql, params = b:whereIn("job", { "police", "medic", "fire" }):toSQL()
T.match(sql, "`job` IN %(%?, %?, %?%)", "whereIn array: SQL correct")
T.eq(params[1], "police", "whereIn array: param 1")
T.eq(params[3], "fire", "whereIn array: param 3")

-- whereNotIn with array
b = BuilderLib.new("users", nil, nil)
sql, params = b:whereNotIn("id", { 1, 2, 3 }):toSQL()
T.match(sql, "`id` NOT IN %(%?, %?, %?%)", "whereNotIn array: SQL correct")

-- whereBetween
b = BuilderLib.new("users", nil, nil)
sql, params = b:whereBetween("money", 100, 5000):toSQL()
T.match(sql, "`money` BETWEEN %? AND %?", "whereBetween: SQL correct")
T.eq(params[1], 100, "whereBetween: min param")
T.eq(params[2], 5000, "whereBetween: max param")

-- whereNotBetween
b = BuilderLib.new("users", nil, nil)
sql = b:whereNotBetween("money", 0, 100):toSQL()
T.match(sql, "`money` NOT BETWEEN %? AND %?", "whereNotBetween: SQL correct")

-- whereLike
b = BuilderLib.new("users", nil, nil)
sql, params = b:whereLike("name", "%john%"):toSQL()
T.match(sql, "`name` LIKE %?", "whereLike: SQL correct")
T.eq(params[1], "%john%", "whereLike: param correct")

-- orderByDesc
b = BuilderLib.new("users", nil, nil)
sql = b:orderByDesc("money"):toSQL()
T.match(sql, "ORDER BY `money` DESC", "orderByDesc: SQL correct")

-- orderByAsc
b = BuilderLib.new("users", nil, nil)
sql = b:orderByAsc("name"):toSQL()
T.match(sql, "ORDER BY `name` ASC", "orderByAsc: SQL correct")

-- latest
b = BuilderLib.new("users", nil, nil)
sql = b:latest():toSQL()
T.match(sql, "ORDER BY `created_at` DESC", "latest: default column")

b = BuilderLib.new("users", nil, nil)
sql = b:latest("updated_at"):toSQL()
T.match(sql, "ORDER BY `updated_at` DESC", "latest: custom column")

-- oldest
b = BuilderLib.new("users", nil, nil)
sql = b:oldest():toSQL()
T.match(sql, "ORDER BY `created_at` ASC", "oldest: default column")

T.finish()
